#include <nuttx/lcd/lcd.h>
#include <nuttx/video/fb.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <unistd.h>
#include <stdio.h>
#include <syslog.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, FAR char *argv[])
{
    int fd;
    int ret;
    struct fb_videoinfo_s vinfo;
    struct fb_planeinfo_s pinfo;
    uint8_t *fbmem;
    size_t fb_size;
    int x, y;

    /* 打开 framebuffer 设备 */
    fd = open("/dev/fb0", O_RDWR);
    if (fd < 0)
    {
        syslog(LOG_ERR, "Failed to open /dev/fb0: %d\n", errno);
        return -errno;
    }

    /* 获取视频信息 */
    ret = ioctl(fd, FBIOGET_VIDEOINFO, (unsigned long)&vinfo);
    if (ret < 0)
    {
        syslog(LOG_ERR, "FBIOGET_VIDEOINFO failed: %d\n", ret);
        close(fd);
        return ret;
    }

    printf("LCD: %dx%d, bpp=%d, nplanes=%d\n",
           vinfo.xres, vinfo.yres, vinfo.bpp, vinfo.nplanes);

    /* 获取平面信息 */
    ret = ioctl(fd, FBIOGET_PLANEINFO, (unsigned long)&pinfo);
    if (ret < 0)
    {
        syslog(LOG_ERR, "FBIOGET_PLANEINFO failed: %d\n", ret);
        close(fd);
        return ret;
    }

    printf("Plane 0: bpp=%d, stride=%d\n", pinfo.bpp, pinfo.stride);

    /* mmap framebuffer */
    fb_size = pinfo.stride * vinfo.yres;
    fbmem = (uint8_t *)mmap(NULL, fb_size, PROT_READ | PROT_WRITE,
                            MAP_SHARED, fd, 0);
    if (fbmem == MAP_FAILED)
    {
        syslog(LOG_ERR, "mmap failed: %d\n", errno);
        close(fd);
        return -errno;
    }

    /* 填充红色 */
    if (pinfo.bpp == 16)
    {
        /* RGB565: 红色 = 0xF800 */
        uint16_t red16 = 0xF800;
        uint16_t *line = (uint16_t *)malloc(vinfo.xres * sizeof(uint16_t));
        if (!line)
        {
            syslog(LOG_ERR, "malloc failed\n");
            munmap(fbmem, fb_size);
            close(fd);
            return -ENOMEM;
        }

        for (x = 0; x < vinfo.xres; x++)
        {
            line[x] = red16;
        }

        for (y = 0; y < vinfo.yres; y++)
        {
            memcpy(fbmem + y * pinfo.stride, line, vinfo.xres * 2);
        }

        free(line);
    }
    else if (pinfo.bpp == 24)
    {
        /* RGB888: 红色 = 0x000000FF (R,G,B) */
        uint8_t *line = (uint8_t *)malloc(vinfo.xres * 3);
        if (!line)
        {
            munmap(fbmem, fb_size);
            close(fd);
            return -ENOMEM;
        }

        for (x = 0; x < vinfo.xres; x++)
        {
            line[x * 3 + 0] = 0x00; /* B */
            line[x * 3 + 1] = 0x00; /* G */
            line[x * 3 + 2] = 0xFF; /* R */
        }

        for (y = 0; y < vinfo.yres; y++)
        {
            memcpy(fbmem + y * pinfo.stride, line, vinfo.xres * 3);
        }

        free(line);
    }
    else if (pinfo.bpp == 32)
    {
        /* ARGB8888: 红色 = 0x00FF0000 */
        uint32_t red32 = 0x00FF0000;
        uint32_t *line = (uint32_t *)malloc(vinfo.xres * sizeof(uint32_t));
        if (!line)
        {
            munmap(fbmem, fb_size);
            close(fd);
            return -ENOMEM;
        }

        for (x = 0; x < vinfo.xres; x++)
        {
            line[x] = red32;
        }

        for (y = 0; y < vinfo.yres; y++)
        {
            memcpy(fbmem + y * pinfo.stride, line, vinfo.xres * 4);
        }

        free(line);
    }
    else
    {
        syslog(LOG_WARNING, "Unsupported bpp: %d\n", pinfo.bpp);
    }

    printf("Red screen displayed!\n");

    /* 保持显示 10 秒 */
    sleep(10);

    munmap(fbmem, fb_size);
    close(fd);

    return 0;
}

